# ================================================================ practice questions
Q_ASK = 'הטענה / הטענות הנכונה / הנכונות:'
VD = {'ok': 'נכונה', 'bad': 'שגויה', 'na': 'לא רלוונטי'}


def CLM(tag, v, paras, n=0, big=''):
    inner = (f'<div><div class="tg">{TX(tag)}</div><span class="vd {v}">{VD[v]}</span></div><div class="bd">' + ''.join(f'<p>{TX(p)}</p>' for p in paras) + '</div>')
    cl = f'clm {big}' if big else 'clm'
    return ST(n, inner, cls=cl) if n else f'<div class="{cl}">{inner}</div>'


def PQ(n, title, stem, claims, opts, a, why, sols, ans, ask=Q_ASK, extra=None):
    """A practice question: the question slide, then solution slides with one reveal per claim.
    stem: list of paragraphs. claims: list of claim sentences, or None when the options are the claims.
    sols: list of slides; a slide is a list of (tag, verdict, paragraphs). extra: html appended to the last solution slide."""
    name = f'שאלת תרגול {n}'
    head = f'{name}: {title}'
    k = f'חלק {CUR[0]} · {name}'
    stem_h = ''.join(f'<p>{TX(x)}</p>' for x in stem)
    claim_h = ''.join(f'<p><b>טענה {i + 1}:</b> {TX(c)}</p>' for i, c in enumerate(claims or []))
    q_mc = mc(f'pq{n}', ask if claims else (stem[-1] if len(stem) == 1 and not claims else ask), opts, a, why)
    if MODE == 'pdf':
        st = '' if not claims and len(stem) == 1 else stem_h
        b = (f'<div class="qstem">{st}{claim_h}</div>' if st or claim_h else '') + q_mc
        for sl in sols:
            for tag, v, ps in sl:
                b += CLM(tag, v, ps)
        b += f'<div class="band ans"><b>תשובה:</b> {TX(ans)}</div>' + (extra or '')
        S(f'q{n}', head, head, b, kind='q')
        return
    if claims:
        body = f'<div class="pqg"><div class="card qstem">{stem_h}{claim_h}</div>{q_mc}</div>'
    else:
        st = '' if len(stem) == 1 else f'<div class="card qstem">{stem_h}</div>'
        body = f'<div class="pqw mcwide">{st}{q_mc}</div>'
    S(f'q{n}', head, head, body, kick=k, cls='qslide')
    for i, sl in enumerate(sols):
        last = i == len(sols) - 1
        # short solutions get larger type, so that the board is used
        chars = sum(len(p) for _, _, ps in sl for p in ps)
        big = 'xl' if chars < 420 and len(sl) <= 3 else 'big' if (chars < 800 and len(sl) <= 4) or len(sl) == 1 else ''
        h = ''.join(CLM(t, v, ps, j + 1, big) for j, (t, v, ps) in enumerate(sl))
        if last:
            h += ST(len(sl) + 1, f'<b>תשובה:</b> {TX(ans)}', cls='band ans') + (extra or '')
        sid = f'q{n}s' + ('' if not i else str(i + 1))
        tt = f'פתרון שאלה {n}' + ('' if len(sols) == 1 else f' ({i + 1} מתוך {len(sols)})')
        S(sid, tt, f'פתרון שאלת תרגול {n}' + ('' if len(sols) == 1 else f' ({i + 1} מתוך {len(sols)})'), h, kick=k, cls='qslide')


